  const orig = $('Prepare AI Prompt').first().json.originalInput;
  return [{ json: {
    success: true,
    aiGenerated: false,
    shuttleRouteId: orig.shuttleRouteId || "SHTL-METRO-01",
    routeName: orig.routeName || "Community Gate 1 <-> Metro Feeder",
    projectedOccupancyPct: 88.0,
    capacityRisk: "MODERATE",
    recommendedFrequencyMinutes: 12,
    deployBackupShuttle: false,
    optimalDepartureWindow: "08:15 AM - 09:30 AM",
    passengerSafetyDirectives: ["Maintain scheduled 12-min loop", "Monitor turnstile queue"],
    auditTimestamp: new Date().toISOString()
  } }];
}
